import attr

class MyClass:
    def __attrs_pre_init__(self, a=None, b=None):
        self.pre_init_a = a
        self.pre_init_b = b

@attr.s(cls=MyClass)
class MyClassAttr:
    a = attr.ib()
    b = attr.ib()

# If the fix is working, the arguments passed to __init__ should be passed to __attrs_pre_init__
# even if the original implementation might have skipped it based on some configuration.
# Actually, the issue was that if pre_init_has_args was False, it wouldn't pass them.
# In the case of MyClass, __attrs_pre_init__ has arguments, so pre_init_has_args should be True.

# Let's test a case where it might have failed before.
# If the user defined __attrs_pre_init__ without arguments, it would have been called without them.
# But the requirement is "Values given to __init__ should now always be propagated".

class MyClassNoArgs:
    def __attrs_pre_init__(self):
        # This will fail if arguments are passed and it doesn't accept them.
        # But the fix says we SHOULD pass them.
        pass

@attr.s(cls=MyClassNoArgs)
class MyClassNoArgsAttr:
    a = attr.ib()

try:
    MyClassNoArgsAttr(a=1)
except TypeError as e:
    print(f"Caught expected TypeError: {e}")
except Exception as e:
    print(f"Caught unexpected exception: {type(e).__name__}: {e}")
else:
    print("No TypeError raised")

# Now let's test the actual intended behavior: propagation to a method that CAN accept them.
class MyClassAcceptsArgs:
    def __attrs_pre_init__(self, *args, **kwargs):
        self.received_args = args
        self.received_kwargs = kwargs

@attr.s(cls=MyClassAcceptsArgs)
class MyClassAcceptsArgsAttr:
    a = attr.ib()
    b = attr.ib()

obj = MyClassAcceptsArgsAttr(a=1, b=2)
# The generated __init__ should call __attrs_pre_init__(a=1, b=2)
# Note: attrs usually passes them as keyword arguments if they are defined as such.
assert obj.received_kwargs == {'a': 1, 'b': 2}, f"Expected {{'a': 1, 'b': 2}}, got {obj.received_kwargs}"
print("Propagation test passed!")
EOF
